                    r += 1
                    continue
                start = r
                while r < h and grid[r][c] == color:
                    r += 1
                if r - start >= 3:
                    runs.append((color, [(y, c) for y in range(start, r)]))

    choices = []
    for color, run in runs:
        for obj_color, cells in comps:
